sys_script_fix.script:
//Scheduled Job


var managerList = [];

var ga = new GlideAggregate("sys_user");
ga.addEncodedQuery("manager!=NULL");
ga.groupBy("manager"); // This automatically removes duplicates
ga.query();
while (ga.next()) {
    managerList.push(ga.getValue("manager") + "");
}

gs.info('managerList ' + managerList.toString());

if (managerList.length > 0) {

    for (var i = 0; i < managerList.length; i++) {
        var managerSysId = managerList[i].toString();
        var employeestoSend = [];
        var managerName = '';

        // Use GlideRecord to fetch user records
        var getEmployeeList = new GlideRecord("sys_user");
        getEmployeeList.addQuery("manager", managerSysId);
        getEmployeeList.query();

        while (getEmployeeList.next()) {
            // Capture the manager name once
            if (!managerName) {
                managerName = getEmployeeList.manager.email;
            }
            // Collect employee names
            employeestoSend.push(getEmployeeList.sys_id.toString() + " "); 
        }

        if (employeestoSend.length > 0) {
            gs.info('Manager: ' + managerName + ' | Employees: ' + employeestoSend.join(', '));

			gs.eventQueue('x_938076_now_utils.manager.intimation',getEmployeeList,managerName,employeestoSend);

        }
    }
}


//Email Script

(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {

    // Add your code here

    var manger = event.parm1; //manager Email
    var employeees = event.parm2; //emplyee sys id array


    var employeeNames = [];
    var employeeEmails = [];

    for (var i = 0; i < employeees.length; i++) {

        var gr = new GlideRecord("sys_user");
        gr.get("sys_id=" + employeees[i]);
        employeeEmails.push(gr.email + " "); //storing emains
        employeeNames.push(gr.user_name + " "); // storing employee name

    }


    for (var j = 0; j < employeeEmails.length; j++) {
        email.addAddress("cc", employeeEmails[j]);
    }
    if (employeeNames.length > 0) {


        template.print('Please find the below employees under you for pending timesheet');

        // Open table markup with inline styling for email clients
        template.print('<table style="border-collapse: collapse; width: 100%; border: 1px solid #ddd; font-family: sans-serif;">');

        // Table Header
        template.print('<thead>');
        template.print('  <tr style="background-color: #f2f2f2; border-bottom: 2px solid #ddd;">');
        template.print('    <th style="padding: 10px; border: 1px solid #ddd; text-align: center; width: 15%;">S.No</th>');
        template.print('    <th style="padding: 10px; border: 1px solid #ddd; text-align: left;">Employee Name</th>');
        template.print('  </tr>');
        template.print('</thead>');

        // Table Body
        template.print('<tbody>');

        for (var k = 0; k < employeeNames.length; k++) {
            var serialNo = k + 1;
            // Alternating row colors for better visibility
            var rowColor = (serialNo % 2 === 0) ? '#f9f9f9' : '#ffffff';

            template.print('  <tr style="background-color: ' + rowColor + ';">');
            template.print('    <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">' + serialNo + '</td>');
            template.print('    <td style="padding: 8px; border: 1px solid #ddd;">' + employeeNames[k] + '</td>');
            template.print('  </tr>');
        }

        template.print('</tbody>');
        template.print('</table>');

    }


})(current, template, email, email_action, event);


